('mission-scramble-1', 'scramble', 'mission', 'Word Scramble', 'words', 1, array['any','office','learning','helpdesk','hr','stg']::text[], 'Each teammate holds one scrambled office or tech word. Unscramble all three.', '{"scout":{"title":"Word 1","body":"O R D B A Y K E\n\nClue: you type on it\n\n(8 letters · starts with K)","mono":true,"big":false},"decoder":{"title":"Word 2","body":"I N O R T M O\n\nClue: a screen\n\n(7 letters · starts with M)","mono":true,"big":false},"intel":{"title":"Word 3","body":"E T I R P R N\n\nClue: puts pages on paper\n\n(7 letters · starts with P)","mono":true,"big":false}}'::jsonb, '[{"label":"Word 1 (Scout)","accept":["KEYBOARD"]},{"label":"Word 2 (Decoder)","accept":["MONITOR"]},{"label":"Word 3 (Intel)","accept":["PRINTER"]}]'::jsonb, false, 3, 200, 'Say the clue out loud first — it narrows the word down. Answers start with: KE…, MO…, PR…', 'KEYBOARD: unscrambled (you type on it) | MONITOR: unscrambled (a screen) | PRINTER: unscrambled (puts pages on paper)', null, 25, 'published'),
('mission-scramble-2', 'scramble', 'mission', 'Word Scramble', 'words', 1, array['any','office','learning','helpdesk','hr','stg']::text[], 'Each teammate holds one scrambled office or tech word. Unscramble all three.', '{"scout":{"title":"Word 1","body":"K W N R T E O\n\nClue: connected computers\n\n(7 letters · starts with N)","mono":true,"big":false},"decoder":{"title":"Word 2","body":"S D R W P S O A\n\nClue: keep it secret\n\n(8 letters · starts with P)","mono":true,"big":false},"intel":{"title":"Word 3","body":"I E N M T G E\n\nClue: calendar invite\n\n(7 letters · starts with M)","mono":true,"big":false}}'::jsonb, '[{"label":"Word 1 (Scout)","accept":["NETWORK"]},{"label":"Word 2 (Decoder)","accept":["PASSWORD"]},{"label":"Word 3 (Intel)","accept":["MEETING"]}]'::jsonb, false, 3, 200, 'Say the clue out loud first — it narrows the word down. Answers start with: NE…, PA…, ME…', 'NETWORK: unscrambled (connected computers) | PASSWORD: unscrambled (keep it secret) | MEETING: unscrambled (calendar invite)', null, 25, 'published'),
('mission-scramble-3', 'scramble', 'mission', 'Word Scramble', 'words', 1, array['any','office','learning','helpdesk','hr','stg']::text[], 'Each teammate holds one scrambled office or tech word. Unscramble all three.', '{"scout":{"title":"Word 1","body":"I A D L D E E N\n\nClue: due date\n\n(8 letters · starts with D)","mono":true,"big":false},"decoder":{"title":"Word 2","body":"N A M A R G E\n\nClue: leads a team\n\n(7 letters · starts with M)","mono":true,"big":false},"intel":{"title":"Word 3","body":"I R A T G N I N\n\nClue: learning session\n\n(8 letters · starts with T)","mono":true,"big":false}}'::jsonb, '[{"label":"Word 1 (Scout)","accept":["DEADLINE"]},{"label":"Word 2 (Decoder)","accept":["MANAGER"]},{"label":"Word 3 (Intel)","accept":["TRAINING"]}]'::jsonb, false, 3, 200, 'Say the clue out loud first — it narrows the word down. Answers start with: DE…, MA…, TR…', 'DEADLINE: unscrambled (due date) | MANAGER: unscrambled (leads a team) | TRAINING: unscrambled (learning session)', null, 25, 'published'),
('mission-scramble-4', 'scramble', 'mission', 'Word Scramble', 'words', 1, array['any','office','learning','helpdesk','hr','stg']::text[], 'Each teammate holds one scrambled office or tech word. Unscramble all three.', '{"scout":{"title":"Word 1","body":"J R T P C O E\n\nClue: a piece of work\n\n(7 letters · starts with P)","mono":true,"big":false},"decoder":{"title":"Word 2","body":"I N T S R P\n\nClue: agile iteration\n\n(6 letters · starts with S)","mono":true,"big":false},"intel":{"title":"Word 3","body":"B O G A C L K\n\nClue: list of work items\n\n(7 letters · starts with B)","mono":true,"big":false}}'::jsonb, '[{"label":"Word 1 (Scout)","accept":["PROJECT"]},{"label":"Word 2 (Decoder)","accept":["SPRINT"]},{"label":"Word 3 (Intel)","accept":["BACKLOG"]}]'::jsonb, false, 3, 200, 'Say the clue out loud first — it narrows the word down. Answers start with: PR…, SP…, BA…', 'PROJECT: unscrambled (a piece of work) | SPRINT: unscrambled (agile iteration) | BACKLOG: unscrambled (list of work items)', null, 25, 'published')
on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category,
  difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts,
  relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint,
  explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status,
  version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts
                 then mission_templates.version + 1 else mission_templates.version end,
  updated_at = now();
